from functools import lru_cache

from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    app_name: str = "CustodeAI API"
    app_env: str = "development"
    api_prefix: str = "/api/v1"
    database_url: str = "sqlite:///./custodeai.db"
    telegram_bot_token: str = ""
    telegram_webhook_secret: str = ""
    public_base_url: str = "http://localhost:8000"
    openai_api_key: str = ""
    openai_model: str = "gpt-4.1-mini"
    storage_dir: str = "storage/tmp"
    reminder_days_before: int = 3
    reminder_hour: int = Field(default=9, ge=0, le=23)
    reminder_minute: int = Field(default=0, ge=0, le=59)
    default_timezone: str = "Europe/Rome"
    scheduler_poll_seconds: int = Field(default=60, ge=15, le=3600)
    sqlalchemy_echo: bool = False

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
    )

    @property
    def telegram_webhook_url(self) -> str:
        base = self.public_base_url.rstrip("/")
        suffix = self.api_prefix.rstrip("/") + "/telegram/webhook"
        return base + suffix


@lru_cache
def get_settings():
    return Settings()

